# Load all grids from session
import os, re
d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

print("Loaded grids:", sorted(G.keys()))
for k, v in sorted(G.items()):
    print(f"\n{k} ({len(v)}x{len(v[0])}):")
    for row in v:
        print(row)

# Recalculate with correct indexing
left_side = [[demo_in[r][c] for c in range(13)] for r in range(h)]
right_side = [[demo_in[r][c+14] for c in range(13)] for r in range(h)]

def compute_xor(left, right):
    result = []
    for r in range(len(left)):
        row = []
        for c in range(len(left[r])):
            if left[r][c] != right[r][c]:
                row.append(2)
            else:
                row.append(0)
        result.append(row)
    return result

computed_out = compute_xor(left_side, right_side)
match = computed_out == demo_out
print(f"Corrected XOR test: {'MATCH' if match else 'NO MATCH'}")
if not match:
    for r in range(min(h, 3)):
        print(f"Row {r}: computed={computed_out[r]}, expected={demo_out[r]}")

# Let me analyze what determines output=2 more carefully
demo_in = G['Demo pair 1 input']
demo_out = G['Demo pair 1 output']

output_positions = []
for r in range(h):
    for c in range(13):
        if demo_out[r][c] == 2:
            left_val = demo_in[r][c]
            right_val = demo_in[r][c+14]
            output_positions.append((r, c, left_val, right_val))

print("All positions where output is 2:")
for r, c, l, rr in sorted(output_positions):
    print(f"({r},{c}): left={l}, right={rr}")

# Verify the new hypothesis: output=2 iff left=3 AND right=9
left_side = [[demo_in[r][c] for c in range(13)] for r in range(h)]
right_side = [[demo_in[r][c+14] for c in range(13)] for r in range(h)]

def compute_rule(left, right):
    result = []
    for r in range(len(left)):
        row = []
        for c in range(len(left[r])):
            if left[r][c] == 3 and right[r][c] == 9:
                row.append(2)
            else:
                row.append(0)
        result.append(row)
    return result

computed_out = compute_rule(left_side, right_side)
match = computed_out == demo_out
print(f"Rule test (left==3 AND right==9): {'MATCH' if match else 'NO MATCH'}")
if not match:
    for r in range(h):
        print(f"Row {r}: computed={computed_out[r]}, expected={demo_out[r]}")

